namespace Store;

public sealed class ShoppingCart
{
    private readonly Dictionary<string, (int Quantity, decimal Price)> _items = new();
    private string? _couponCode;

    public void AddItem(string sku, int quantity, decimal price)
    {
        if (string.IsNullOrEmpty(sku))
            throw new ArgumentException("SKU cannot be null or empty.", nameof(sku));
        if (quantity <= 0)
            throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be greater than zero.");
        if (price < 0)
            throw new ArgumentOutOfRangeException(nameof(price), "Price cannot be negative.");

        if (_items.TryGetValue(sku, out var existing))
            _items[sku] = (existing.Quantity + quantity, price);
        else
            _items[sku] = (quantity, price);
    }

    public void RemoveItem(string sku)
    {
        if (string.IsNullOrEmpty(sku))
            throw new ArgumentException("SKU cannot be null or empty.", nameof(sku));
        if (!_items.Remove(sku))
            throw new InvalidOperationException($"SKU '{sku}' not found in cart.");
    }

    public decimal CalculateTotal()
    {
        var subtotal = _items.Values.Sum(item => item.Quantity * item.Price);

        var discount = _couponCode switch
        {
            "SAVE10" => subtotal * 0.10m,
            "FLAT5" => 5m,
            _ => 0m
        };

        return Math.Max(0m, subtotal - discount);
    }

    public void ApplyCoupon(string code)
    {
        if (string.IsNullOrEmpty(code))
            throw new ArgumentException("Coupon code cannot be null or empty.", nameof(code));
        if (code is not ("SAVE10" or "FLAT5"))
            throw new ArgumentException($"Unrecognized coupon code '{code}'.", nameof(code));

        _couponCode = code;
    }
}

using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Store.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    #region AddItem and CalculateTotal

    [TestMethod]
    public void AddItem_SingleItem_CalculatesCorrectTotal()
    {
        _cart.AddItem("SKU1", 2, 10.00m);
        Assert.AreEqual(20.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_CalculatesCorrectTotal()
    {
        _cart.AddItem("SKU1", 1, 10.00m);
        _cart.AddItem("SKU2", 3, 5.00m);
        Assert.AreEqual(25.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_QuantityAccumulates()
    {
        _cart.AddItem("SKU1", 2, 10.00m);
        _cart.AddItem("SKU1", 3, 10.00m);
        Assert.AreEqual(50.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    #endregion

    #region RemoveItem

    [TestMethod]
    public void RemoveItem_ExistingItem_UpdatesTotal()
    {
        _cart.AddItem("SKU1", 1, 10.00m);
        _cart.AddItem("SKU2", 2, 5.00m);
        _cart.RemoveItem("SKU1");
        Assert.AreEqual(10.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_OnlyItem_TotalBecomesZero()
    {
        _cart.AddItem("SKU1", 3, 7.00m);
        _cart.RemoveItem("SKU1");
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsInvalidOperationException()
    {
        Assert.ThrowsException<InvalidOperationException>(() => _cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    public void RemoveItem_NullSku_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.RemoveItem(null!));
    }

    [TestMethod]
    public void RemoveItem_EmptySku_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.RemoveItem(""));
    }

    #endregion

    #region ApplyCoupon

    [TestMethod]
    public void ApplyCoupon_Save10_Gives10PercentOff()
    {
        _cart.AddItem("SKU1", 1, 100.00m);
        _cart.ApplyCoupon("SAVE10");
        Assert.AreEqual(90.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_Flat5_GivesFiveDollarsOff()
    {
        _cart.AddItem("SKU1", 1, 20.00m);
        _cart.ApplyCoupon("FLAT5");
        Assert.AreEqual(15.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_Flat5_TotalFloorsAtZero()
    {
        _cart.AddItem("SKU1", 1, 3.00m);
        _cart.ApplyCoupon("FLAT5");
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_NewCouponReplacesPrevious()
    {
        _cart.AddItem("SKU1", 1, 100.00m);
        _cart.ApplyCoupon("SAVE10");
        _cart.ApplyCoupon("FLAT5");
        Assert.AreEqual(95.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_NullCode_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon(null!));
    }

    [TestMethod]
    public void ApplyCoupon_EmptyCode_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon(""));
    }

    [TestMethod]
    public void ApplyCoupon_UnknownCode_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon("BOGUS"));
    }

    #endregion

    #region AddItem Validation

    [TestMethod]
    public void AddItem_NullSku_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.AddItem(null!, 1, 10.00m));
    }

    [TestMethod]
    public void AddItem_EmptySku_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.AddItem("", 1, 10.00m));
    }

    [TestMethod]
    public void AddItem_ZeroQuantity_ThrowsArgumentOutOfRangeException()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU1", 0, 10.00m));
    }

    [TestMethod]
    public void AddItem_NegativeQuantity_ThrowsArgumentOutOfRangeException()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU1", -1, 10.00m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_ThrowsArgumentOutOfRangeException()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU1", 1, -5.00m));
    }

    #endregion
}

